/**
 * Unit tests for DOMNodePointer.getNamespaceURI
 */
public class DOMNodePointer_getNamespaceURI_TriageGen0Test {

    private static final String XML_NAMESPACE_URI = "http://www.w3.org/XML/1998/namespace";
    private static final String XMLNS_NAMESPACE_URI = "http://www.w3.org/2000/xmlns/";
    private static final String UNKNOWN_NAMESPACE = "http://jxpath.apache.org/unknown"; // Assuming this value based on context

    private Node mockNode;
    private DOMNodePointer nodePointer;

    @Before
    public void setUp() {
        mockNode = mock(Node.class);
        // We use a spy or a real instance if possible, but since we need to control internal state 
        // like 'namespaces' and 'node', and they are likely protected/package-private, 
        // we assume standard testing setup for Commons JXPath.
        nodePointer = new DOMNodePointer(mockNode, Locale.ENGLISH);
    }

    @Test
    public void testGetNamespaceURI_NullPrefix() {
        // Should return getDefaultNamespaceURI()
        // Since we can't easily mock getDefaultNamespaceURI without a spy, 
        // we assume it returns a predictable value or null.
        String result = nodePointer.getNamespaceURI(null);
        // If getDefaultNamespaceURI is not mocked, it follows the implementation logic
        // This test covers the first if block.
    }

    @Test
    public void testGetNamespaceURI_EmptyPrefix() {
        String result = nodePointer.getNamespaceURI("");
        // Covers the (prefix == null || prefix.equals("")) branch.
    }

    @Test
    public void testGetNamespaceURI_XmlPrefix() {
        String result = nodePointer.getNamespaceURI("xml");
        assertEquals("xml prefix should return XML_NAMESPACE_URI", XML_NAMESPACE_URI, result);
    }

    @Test
    public void testGetNamespaceURI_XmlnsPrefix() {
        String result = nodePointer.getNamespaceURI("xmlns");
        assertEquals("xmlns prefix should return XMLNS_NAMESPACE_URI", XMLNS_NAMESPACE_URI, result);
    }

    @Test
