        Document doc = mock(Document.class);
        Element root = mock(Element.class);
        when(doc.getDocumentElement()).thenReturn(root);
        when(root.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(root.getParentNode()).thenReturn(null);

        // This tests the branch where the pointer's node is a Document
        // We need a way to inject 'doc' into nodePointer.
    }

