        // Test 'if (namespace == null || namespace.equals(""))'
        String prefix = "empty";
        Element element = mock(Element.class);
        Attr attr = mock(Attr.class);

        when(mockNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(mockNode.getParentNode()).thenReturn(null);
        when(element.getAttributeNode("xmlns:empty")).thenReturn(attr);
        when(attr.getValue()).thenReturn(""); // Empty string case

